parameters.jsCode:
// Get data from previous nodes
const aiOutput = $input.first().json;
const webhookData = $('Webhook').first().json.body;
const insertedData = $('Insert rows in a table1').first().json;

// Extract database IDs
const requestId = insertedData.request_id;
const databaseId = insertedData.id;

// Parse AI output (handle both string and object formats)
let parsedAI;
try {
  if (typeof aiOutput.output === 'string') {
    let cleanOutput = aiOutput.output.trim();

    // Remove markdown code blocks if present
    if (cleanOutput.startsWith('```')) {
      cleanOutput = cleanOutput.split('\n').slice(1, -1).join('\n');
    }

    parsedAI = JSON.parse(cleanOutput);
  } else {
    parsedAI = aiOutput.output || aiOutput;
  }
} catch (error) {
  console.error('Failed to parse AI output:', error);
  parsedAI = {}; // Fallback to empty object
}

// Return combined data structure
return {
  json: {
    // Database IDs
    id: databaseId,
    request_id: requestId,

    // AI Analysis
    urgency: parsedAI.urgency || 'medium',
    category: parsedAI.category || 'general',
    summary: parsedAI.summary || webhookData.issue_description || '',
    handyman_notes: parsedAI.handyman_notes || parsedAI.summary || '',
    requires_photos: parsedAI.requires_photos || false,
    estimated_time: parsedAI.estimated_time || '1-2hrs',

    // Vendor information from AI Agent
    assigned_vendor_id: parsedAI.vendor_id || null,
    vendor_name: parsedAI.vendor_name || null,
    vendor_phone: parsedAI.vendor_phone || null,
    vendor_email: parsedAI.vendor_email || null,

    // Backward compatibility fields
    primary_vendor_name: parsedAI.vendor_name || null,
    primary_vendor_phone: parsedAI.vendor_phone || null,
    backup_vendor_phone: parsedAI.vendor_phone || null,

    // Original webhook data
    tenant_name: webhookData.tenant_name || 'Unknown',
    tenant_phone: webhookData.tenant_phone || webhookData.phone_number || '',
    property_address: webhookData.property_address || '',
    apartment_unit: webhookData.apartment_unit || '',
    issue_description: webhookData.issue_description || '',

    // Metadata
    date_created: new Date().toISOString(),
    status: 'pending',
    landlord_email: "your-email@example.com",
    landlord_name: "Test Landlord"
  }
};

